  function openPanel() {
    const root = uiDocument.getElementById(ROOT_ID);
    if (!root) return;
    root.querySelector('.lps-panel').hidden = false;
    root.querySelector('.lps-backdrop').hidden = false;
    renderAll();
    if (!state.tavernPresets.length && !state.tavernPresetsLoading) {
      refreshTavernPresets({ silent: true }).catch(() => {});
    }
  }

  function closePanel() {
    const root = uiDocument.getElementById(ROOT_ID);
    if (!root) return;
    root.querySelector('.lps-panel').hidden = true;
    root.querySelector('.lps-backdrop').hidden = true;
  }

  function makeFabDraggable(fab) {
    let startX = 0;
    let startY = 0;
    let originX = 0;
    let originY = 0;
    let moved = false;
    let dragJustEnded = false;
    const storageKey = 'ling-preset-stitcher-fab-pos-v1';
    try {
      const saved = JSON.parse(uiWindow.localStorage?.getItem(storageKey) || 'null');
      if (saved && Number.isFinite(saved.left) && Number.isFinite(saved.top)) {
        fab.style.left = `${saved.left}px`;
        fab.style.top = `${saved.top}px`;
        fab.style.right = 'auto';
        fab.style.bottom = 'auto';
      }
    } catch {}

    const onMove = event => {
      const dx = event.clientX - startX;
      const dy = event.clientY - startY;
      if (Math.abs(dx) + Math.abs(dy) > 6) moved = true;
      const left = Math.max(4, Math.min(uiWindow.innerWidth - fab.offsetWidth - 4, originX + dx));
      const top = Math.max(4, Math.min(uiWindow.innerHeight - fab.offsetHeight - 4, originY + dy));
      fab.style.left = `${left}px`;
      fab.style.top = `${top}px`;
      fab.style.right = 'auto';
      fab.style.bottom = 'auto';
    };
    const onUp = () => {
      uiWindow.removeEventListener('pointermove', onMove);
      uiWindow.removeEventListener('pointerup', onUp);
      dragJustEnded = moved;
      if (moved) {
        try {
          uiWindow.localStorage?.setItem(storageKey, JSON.stringify({
            left: parseFloat(fab.style.left),
            top: parseFloat(fab.style.top),
          }));
        } catch {}
      }
    };
    fab.addEventListener('pointerdown', event => {
      startX = event.clientX;
      startY = event.clientY;
      const rect = fab.getBoundingClientRect();
      originX = rect.left;
      originY = rect.top;
      moved = false;
      dragJustEnded = false;
      uiWindow.addEventListener('pointermove', onMove);
      uiWindow.addEventListener('pointerup', onUp, { once: true });
    });
    fab.addEventListener('click', event => {
      if (dragJustEnded) {
        dragJustEnded = false;
        event.preventDefault();
        return;
      }
      openPanel();
    });
  }

  function mount() {
    uiDocument.getElementById(ROOT_ID)?.remove();
    uiDocument.getElementById(STYLE_ID)?.remove();

    const style = uiDocument.createElement('style');
    style.id = STYLE_ID;
    style.textContent = styleText();
    uiDocument.head.appendChild(style);

    const root = uiDocument.createElement('div');
    root.id = ROOT_ID;
    try {
      root.setAttribute('script_id', typeof getScriptId === 'function' ? getScriptId() : ROOT_ID);
    } catch {}
    root.innerHTML = panelTemplate();
    uiDocument.body.appendChild(root);

    makeFabDraggable(root.querySelector('.lps-fab'));
    root.querySelector('.lps-close').addEventListener('click', closePanel);
    root.querySelector('.lps-backdrop').addEventListener('click', closePanel);
    root.querySelector('.lps-refresh-presets').addEventListener('click', () => {
      refreshTavernPresets().catch(handleError);
    });
    root.querySelector('.lps-load-base-preset').addEventListener('click', () => {
      loadTavernBase().catch(handleError);
    });
    root.querySelector('.lps-add-donor-preset').addEventListener('click', () => {
      addTavernDonor().catch(handleError);
    });
    root.querySelector('.lps-clear-donors').addEventListener('click', clearDonors);
    root.querySelector('.lps-base-input').addEventListener('change', event => {
      const file = event.target.files?.[0];
      if (file) {
        loadBase(file)
          .catch(handleError)
          .finally(() => {
            event.target.value = '';
          });
      }
    });
    root.querySelector('.lps-donor-input').addEventListener('change', event => {
      const files = [...(event.target.files || [])];
      if (files.length) {
        loadDonors(files)
          .catch(handleError)
          .finally(() => {
            event.target.value = '';
          });
      }
    });
    root.querySelector('.lps-search').addEventListener('input', event => {
      state.query = event.target.value;
      renderComponents();
    });
    root.querySelector('.lps-kind-tabs').addEventListener('click', event => {
      const tab = event.target.closest('[data-kind-tab]');
      if (!tab || tab.disabled) return;
      state.activeKind = tab.dataset.kindTab;
      renderKindTabs();
      renderComponents();
    });
    root.querySelector('.lps-component-list').addEventListener('change', event => {
      const checkbox = event.target.closest('[data-component-key]');
      if (!checkbox) return;
      checkbox.checked ? state.selected.add(checkbox.dataset.componentKey) : state.selected.delete(checkbox.dataset.componentKey);
      updateSelectionCount();
    });
    root.querySelector('.lps-component-list').addEventListener('click', event => {
      const selectButton = event.target.closest('[data-select-donor]');
      const clearButton = event.target.closest('[data-clear-donor]');
      const removeButton = event.target.closest('[data-remove-donor]');
      if (removeButton) {
        removeDonor(removeButton.dataset.removeDonor);
        return;
      }
      if (selectButton) {
        const donor = state.donors.find(value => value.id === selectButton.dataset.selectDonor);
        donor?.components.filter(componentMatchesView).forEach(component => state.selected.add(component.key));
        renderComponents();
      }
      if (clearButton) {
        const donor = state.donors.find(value => value.id === clearButton.dataset.clearDonor);
        donor?.components.filter(componentMatchesView).forEach(component => state.selected.delete(component.key));
        renderComponents();
      }
    });
    root.querySelector('.lps-select-all').addEventListener('click', () => {
      getAllComponents().filter(componentMatchesView)
        .forEach(component => state.selected.add(component.key));
      renderComponents();
    });
    root.querySelector('.lps-clear-all').addEventListener('click', () => {
      state.selected.clear();
      renderComponents();
    });
    root.querySelector('.lps-stitch').addEventListener('click', () => {
      performStitch().catch(handleError);
    });
    root.querySelector('.lps-export-pack').addEventListener('click', () => {
      try {
        exportPack();
      } catch (error) {
        handleError(error);
      }
    });
    uiDocument.addEventListener('keydown', onDocumentKeyDown);

    try {
      if (typeof eventOn === 'function' && typeof getButtonEvent === 'function') {
        eventOn(getButtonEvent(BUTTON_NAME), openPanel);
      }
    } catch (error) {
      console.warn('[玲·预设缝合机] 脚本按钮监听失败，悬浮按钮仍可使用。', error);
    }

    renderAll();
    console.info(`[玲·预设缝合机] v${VERSION} 已加载`);
  }

  function cleanup() {
    uiDocument.removeEventListener('keydown', onDocumentKeyDown);
    uiDocument.getElementById(ROOT_ID)?.remove();
    uiDocument.getElementById(STYLE_ID)?.remove();
  }

  if (typeof $ === 'function') {
    $(() => mount());
    $(uiWindow).on('pagehide', cleanup);
  } else if (uiDocument.readyState === 'loading') {
    uiDocument.addEventListener('DOMContentLoaded', mount, { once: true });
    uiWindow.addEventListener('pagehide', cleanup, { once: true });
  } else {
    mount();
    uiWindow.addEventListener('pagehide', cleanup, { once: true });
  }
})();
